"""Generate results/ml/OPENOX_SPO2.md from the aggregate CSVs of openox_spo2.analyze (no number is typed by hand): `python -m oxydrop_ml.openox_spo2 report --res ../results/ml`."""
from __future__ import annotations

import os

import numpy as np
import pandas as pd

LABEL_TEXT = {'lag_star': 'lag-corrected SaO2 (primary)', 'lag_0': 'lag 0 SaO2', 'abg_draws': 'direct ABG draws (one value per draw)'}
MODEL_TEXT = {'R': 'CNN hybrid R members (3 seeds, deployed family)', 'P': 'CNN plain P members (3 seeds)', 'stageB': 'CNN stage-B warm-up (OpenOx only)', 'train_mean': 'train-mean',
              'ror_textbook': 'ratio-of-ratios, textbook 110 - 25 R', 'ror_calibrated': 'ratio-of-ratios, calibrated line (train people)'}
ORDER = ['R', 'P', 'stageB', 'ror_textbook', 'ror_calibrated', 'train_mean']


def f2(x):
    return 'n/a' if not np.isfinite(x) else f'{x:.2f}'


def f3(x):
    return 'n/a' if not np.isfinite(x) else f'{x:.3f}'


def ci2(r, k):
    return f'{f2(r[k])} [{f2(r[k + "_lo"])}, {f2(r[k + "_hi"])}]'


def ci3(r, k):
    return f'{f3(r[k])} [{f3(r[k + "_lo"])}, {f3(r[k + "_hi"])}]'


def table(rows, header):
    out = ['| ' + ' | '.join(header) + ' |', '|' + '---|' * len(header)]
    out += ['| ' + ' | '.join(str(c) for c in r) + ' |' for r in rows]
    return '\n'.join(out)


def report(res):
    rd = lambda n: pd.read_csv(os.path.join(res, f'openox_spo2_{n}.csv'))
    ov, pr, sk, gp, cb, cg, ra, lg, ct = rd('overall'), rd('paired'), rd('skin'), rd('gaps'), rd('contact_bias'), rd('contact_bias_gaps'), rd('ror_all_people'), rd('lag'), rd('counts').iloc[0]
    est = lg[lg.kind == 'estimate'].set_index('method')
    sens = lg[lg.kind == 'sensitivity']
    L = []
    L.append('# OpenOximetry SaO2 test of the OxyDrop CNN (FEAT-007)\n')
    L.append('**This is a contact red/infrared finger-clip sensor test. It is not a phone-camera test and says nothing about how accurate the phone app is.** *Generated by `python/oxydrop_ml/openox_spo2_md.py` from `results/ml/openox_spo2_*.csv`; do not edit by hand. Research prototype, not a medical device.*\n')
    L.append('Protocol: `python/oxydrop_ml/PREREGISTRATION.md` with `amendments/AMENDMENT_5_conformal_openox.md` (Part B, committed before any OpenOx score of these models existed). All rows are secondary and exploratory. OpenOximetry is PhysioNet credentialed data: the analysis ran on a Daytona sandbox only, and only these aggregates are in the repository.\n')
    L.append('## Who is evaluated and what the models have seen\n')
    L.append(f'* {int(ct.heldout_people)} OpenOx people are held out (`train.openox_holdout`, a deterministic Monk-stratified quarter). They are excluded before sampling from the SSL pretraining (`ssl_manifest.json`: 34 excluded subjects), from the stage-B warm-up and from every supervised fit of the hybrid members. The scored checkpoints are the all-Hoffman fits of the hybrid families R and P (3 seeds each) and `stageB_full.pt`; none of them has seen a held-out person. `student_v1.pt` (trained through the same default pool, so it did not see them either) is not scored here.')
    L.append(f'* Of the {int(ct.heldout_people)} held-out people, {int(ct.heldout_people_scored)} have clock-aligned recordings (the only recordings with window labels) and {int(ct.heldout_people_with_sao2)} have an SaO2 label: {int(ct.windows_sao2):,} windows with t >= 60 s; {int(ct.windows_draw):,} windows span a blood-gas draw marker, {int(ct.draws_scored)} draws.')
    L.append(f'* Data facts (what the data has): {int(ct.draws_in_data):,} blood-gas draws with an SaO2 value in {int(ct.draw_encounters)} PPG encounters ({int(ct.draw_people)} people); {int(ct.draws_in_aligned_recordings):,} of them lie in the clock-aligned recordings ({int(ct.draw_people_aligned)} people). SaO2 < 90 occurs in {int(ct.draws_lt90_all):,} draws ({int(ct.people_with_lt90_all)} people); counting a desaturation episode as a run of consecutive draws below 90 the data has {int(ct.episodes_lt90_all)} episodes in all encounters and {int(ct.episodes_lt90_aligned)} episodes in {int(ct.people_with_lt90_aligned)} people with aligned recordings. The figure "466 desaturations in 144 people" could not be traced to any table of the dataset and is not used.')
    L.append(f'* Training people for the baselines and the lag: {int(ct.train_people)} OpenOx people outside the held-out set ({int(ct.train_windows):,} labelled windows at the lag below). Train mean SaO2 {f2(ct.train_mean)}.')
    L.append('* Output scored: the contact-domain SaO2 head `aux_spo2` (domain 1, contact red/IR input). The checkpoints were trained on lag-0 labels, so a lag-corrected evaluation is slightly unfavourable to them. Nothing is fit, tuned or recalibrated on a held-out person.\n')
    L.append('## Label lag\n')
    L.append(f'The contact display trails the finger tissue. The lag was estimated on the {int(ct.train_people)} training people only: **{est.loc["ppg", "lag"]:.0f} s** (bootstrap over {int(est.loc["ppg", "n_encounters"])} encounters: [{est.loc["ppg", "ci_lo"]:.0f}, {est.loc["ppg", "ci_hi"]:.0f}]) from the correlation of the PPG ratio-of-ratios with the display SpO2, and {est.loc["abg", "lag"]:.0f} s [{est.loc["abg", "ci_lo"]:.0f}, {est.loc["abg", "ci_hi"]:.0f}] from the display against the blood-gas draws. The primary label uses {ct.lag_star:.0f} s.\n')
    rows = []
    for m in ('R', 'ror_textbook'):
        s = sens[sens.method == m].sort_values('lag')
        for _, r in s.iterrows():
            if int(r.lag) in (-10, 0, 10, int(ct.lag_star), 30, 60):
                rows.append([MODEL_TEXT[m], int(r.lag), f2(r.mae), f2(r.bias), f2(r.arms_70_100), f3(r.auroc_lt90)])
    L.append('Sensitivity of the held-out scores to the lag used for the labels (descriptive, not used for any choice):\n')
    L.append(table(rows, ['predictor', 'label lag (s)', 'MAE', 'bias (pred - SaO2)', 'ARMS 70-100', 'AUROC SaO2 < 90']))
    L.append('')
    # headline
    for lab in ('lag_star', 'lag_0', 'abg_draws'):
        d = ov[ov.label == lab].set_index('model')
        r0 = d.iloc[0]
        L.append(f'## {LABEL_TEXT[lab][0].upper() + LABEL_TEXT[lab][1:]}: {int(r0.n_windows):,} {"draws" if lab == "abg_draws" else "windows"}, {int(r0.n_people)} people, {100 * r0.prevalence_lt90:.0f}% below 90\n')
        rows = [[MODEL_TEXT[m], ci2(d.loc[m], 'mae'), f2(d.loc[m].person_mae_mean) + ' +- ' + f2(d.loc[m].person_mae_sd), ci2(d.loc[m], 'bias'), ci2(d.loc[m], 'arms_70_100'), ci3(d.loc[m], 'auroc_lt90')] for m in ORDER]
        L.append(table(rows, ['predictor', 'MAE [95% person-bootstrap CI]', 'per-person MAE mean +- SD', 'bias (pred - SaO2)', 'ARMS 70-100 (RMS error)', 'AUROC for SaO2 < 90']))
        L.append('')
        p = pr[(pr.label == lab) & (pr.model == 'R')]
        rows = [[MODEL_TEXT[b], f2(r.model_mae), f2(r.baseline_mae), f'{r.diff_model_minus_baseline:+.2f} [{r.lo:+.2f}, {r.hi:+.2f}]', r.verdict] for _, r in p.iterrows() for b in [r.baseline]]
        L.append('Paired person bootstrap of the MAE difference (hybrid R minus the other predictor; negative = R better):\n')
        L.append(table(rows, ['versus', 'R MAE', 'other MAE', 'difference [95% CI]', 'verdict']))
        L.append('')
    # reading
    d = ov[ov.label == 'lag_star'].set_index('model')
    p = pr[(pr.label == 'lag_star') & (pr.model == 'R')].set_index('baseline')
    pd_ = pr[(pr.label == 'abg_draws') & (pr.model == 'R')].set_index('baseline')
    d0 = ov[ov.label == 'lag_0'].set_index('model')
    L.append('## Reading, computed from the tables\n')
    L.append(f'* **Against the train-mean predictor the CNN is far better** (MAE {f2(d.loc["R", "mae"])} against {f2(d.loc["train_mean", "mae"])}, difference {p.loc["train_mean", "diff_model_minus_baseline"]:+.2f} [{p.loc["train_mean", "lo"]:+.2f}, {p.loc["train_mean", "hi"]:+.2f}]), and AUROC for SaO2 < 90 is {f3(d.loc["R", "auroc_lt90"])}.')
    L.append(f'* **Against the textbook ratio-of-ratios the CNN is not better**: MAE {f2(d.loc["R", "mae"])} against {f2(d.loc["ror_textbook", "mae"])}, difference {p.loc["ror_textbook", "diff_model_minus_baseline"]:+.2f} [{p.loc["ror_textbook", "lo"]:+.2f}, {p.loc["ror_textbook", "hi"]:+.2f}], {p.loc["ror_textbook", "verdict"]}. On the direct blood-gas draws the textbook rule is nominally ahead ({f2(ov[(ov.label == "abg_draws") & (ov.model == "ror_textbook")].iloc[0].mae)} against {f2(ov[(ov.label == "abg_draws") & (ov.model == "R")].iloc[0].mae)}, difference {pd_.loc["ror_textbook", "diff_model_minus_baseline"]:+.2f} [{pd_.loc["ror_textbook", "lo"]:+.2f}, {pd_.loc["ror_textbook", "hi"]:+.2f}], {pd_.loc["ror_textbook", "verdict"]}). On a contact red/infrared sensor the physics rule is hard to beat and the CNN ties it; under the pre-registered rule (a win needs the paired interval against the best baseline to exclude zero) this is a tie, not a win, and it is not evidence about phone accuracy.')
    L.append(f'* The CNN reads {f2(d.loc["R", "bias"])} points above SaO2 on average; the contact oximeter display itself reads {f2(ct.device_display_bias)} points above SaO2 on the same windows (MAE {f2(ct.device_display_mae)}, ARMS 70-100 {f2(ct.device_display_arms_70_100)}, AUROC {f3(ct.device_display_auroc_lt90)}, n = {int(ct.device_display_n):,}). The CNN labels came from that display (mapped to blood gas), so it inherits part of its bias.')
    L.append(f'* **Lag correction**: MAE of the CNN is {f2(d0.loc["R", "mae"])} at lag 0 and {f2(d.loc["R", "mae"])} at {ct.lag_star:.0f} s, the textbook rule {f2(d0.loc["ror_textbook", "mae"])} and {f2(d.loc["ror_textbook", "mae"])}; the CNN is nearly insensitive because it was trained on lag-0 labels, the physics rule gains {d0.loc["ror_textbook", "mae"] - d.loc["ror_textbook", "mae"]:.2f} points.')
    L.append(f'* Among the CNN variants, the stage-B warm-up (MAE {f2(d.loc["stageB", "mae"])}) and R ({f2(d.loc["R", "mae"])}) are tied (difference {pr[(pr.label == "lag_star") & (pr.model == "R") & (pr.baseline == "stageB")].iloc[0].diff_model_minus_baseline:+.2f}); R beats the plain P members ({pr[(pr.label == "lag_star") & (pr.model == "R") & (pr.baseline == "P")].iloc[0].diff_model_minus_baseline:+.2f} [{pr[(pr.label == "lag_star") & (pr.model == "R") & (pr.baseline == "P")].iloc[0].lo:+.2f}, {pr[(pr.label == "lag_star") & (pr.model == "R") & (pr.baseline == "P")].iloc[0].hi:+.2f}]), a small effect on this head.')
    L.append('')
    # skin tone
    L.append('## By skin tone (held-out people, lag-corrected label)\n')
    g = sk[(sk.label == 'lag_star') & (sk.model.isin(['R', 'ror_textbook', 'train_mean'])) & (sk.group != 'unknown')]
    rows = []
    for scheme in ('monk', 'ita'):
        for grp in (['1-3', '4-6', '7+'] if scheme == 'monk' else ['darkest tertile', 'mid tertile', 'lightest tertile']):
            for m in ('R', 'ror_textbook', 'train_mean'):
                r = g[(g.scheme == scheme) & (g.group == grp) & (g.model == m)]
                if len(r):
                    r = r.iloc[0]
                    rows.append([scheme.upper(), grp, MODEL_TEXT[m], int(r.n_people), f'{int(r.n_windows):,}', ci2(r, 'mae'), f2(r.bias), f3(r.auroc_lt90)])
    L.append(table(rows, ['scale', 'group', 'predictor', 'people', 'windows', 'MAE [95% CI]', 'bias', 'AUROC SaO2 < 90']))
    L.append('')
    L.append('Dark-minus-light gaps (darkest minus lightest ITA tertile; Monk 7+ minus 1-3 only with at least 3 people per group), independent person bootstraps:\n')
    rows = []
    for _, r in gp[(gp.label == 'lag_star') & (gp.model.isin(['R', 'ror_textbook', 'train_mean']))].iterrows():
        rows.append([r.scheme.upper(), MODEL_TEXT[r.model], r.metric, f'{int(r.n_dark)} vs {int(r.n_light)}', f'{r.gap:+.2f} [{r.lo:+.2f}, {r.hi:+.2f}]' if r.estimable else 'not estimable (fewer than 3 people in a group)'])
    L.append(table(rows, ['scale', 'predictor', 'metric', 'people dark vs light', 'gap [95% CI]']))
    L.append('')
    gR = gp[(gp.label == 'lag_star') & (gp.model == 'R') & (gp.scheme == 'ita') & (gp.metric == 'mae')].iloc[0]
    gB = gp[(gp.label == 'lag_star') & (gp.model == 'R') & (gp.scheme == 'ita') & (gp.metric == 'bias')].iloc[0]
    L.append(f'The CNN\'s bias is {gB.dark_value:+.2f} points in the darkest ITA tertile and {gB.light_value:+.2f} in the lightest (gap {gB.gap:+.2f} [{gB.lo:+.2f}, {gB.hi:+.2f}]): the sign agrees with the contact oximeter bias below, but the interval contains zero.\n')
    L.append(f'With {int(gR.n_dark)} and {int(gR.n_light)} people per ITA group the CNN\'s dark-minus-light MAE gap is {gR.gap:+.2f} [{gR.lo:+.2f}, {gR.hi:+.2f}]: the interval contains zero, so no skin-tone gap is detected, and it is too wide to rule out a gap of a point or two. The Monk 7+ group has {int(g[(g.scheme == "monk") & (g.group == "7+")].n_people.max())} held-out people, so the Monk gap cannot be estimated on this set. (The amendment counted one Monk 7+ person from the first recording; the person-level median used here gives two.)\n')
    L.append('### Bias of the contact oximeter itself, by skin tone (all blood-gas draws, no model involved)\n')
    L.append('Display SpO2 at the draw minus blood-gas SaO2, person bootstrap. This is the reference problem a camera model trained on pulse-oximeter labels would inherit.\n')
    rows = [[r.scheme.upper(), r.group, int(r.n_people), f'{int(r.n_draws):,}', f'{r.bias:+.2f} [{r.lo:+.2f}, {r.hi:+.2f}]'] for _, r in cb.iterrows()]
    L.append(table(rows, ['scale', 'group', 'people', 'draws', 'display minus SaO2, points [95% CI]']))
    L.append('')
    rows = [[r.scheme.upper(), f'{r.dark} minus {r.light}', f'{int(r.n_dark)} vs {int(r.n_light)}', f'{r.gap:+.2f} [{r.lo:+.2f}, {r.hi:+.2f}]' if r.estimable else 'not estimable'] for _, r in cg.iterrows()]
    L.append(table(rows, ['scale', 'contrast', 'people', 'bias gap [95% CI]']))
    L.append('')
    L.append('### Textbook ratio-of-ratios by skin tone (all aligned OpenOx people, no fitted parameter, descriptive)\n')
    rows = [[r.scheme.upper(), r.group, int(r.n_people), f'{int(r.n_windows):,}', f'{f2(r.mae)} [{f2(r.mae_lo)}, {f2(r.mae_hi)}]', f'{f2(r.bias)} [{f2(r.bias_lo)}, {f2(r.bias_hi)}]'] for _, r in ra.iterrows()]
    L.append(table(rows, ['scale', 'group', 'people', 'windows', 'MAE [95% CI]', 'bias [95% CI]']))
    L.append('')
    L.append('## Limits\n')
    L.append('* Contact finger-clip red/infrared sensor on healthy volunteers with a staircase hypoxia protocol: not a phone, not patients, not field conditions.\n* The continuous SaO2 label is the contact display mapped to blood gas with a per-encounter line fitted on that encounter\'s draws; only the draw rows are a direct blood-gas measurement. Label timing carries the lag uncertainty above.\n* 24 labelled held-out people: every interval is wide, and the Monk 7+ group is nearly empty.\n* The CNN checkpoints were trained on lag-0 labels and without any held-out person; no recalibration was applied.\n* The held-out people are 34 of 137; the other people were used for training and are not a test set. The skin-tone bias table of the contact device uses all of them because no model is involved.\n')
    L.append('## Reproduce\n')
    L.append('```\nbash scripts/reproduce_ml.sh   # STAGE=openox-up, openox-run (Daytona only; see the stage comments), then STAGE=openox-report\n```\n')
    open(os.path.join(res, 'OPENOX_SPO2.md'), 'w').write('\n'.join(L))
    print('wrote', os.path.join(res, 'OPENOX_SPO2.md'))
